<script setup lang="ts">
import { ref, computed, onMounted } from 'vue'
import { ElMessage } from 'element-plus'
import { useSession } from '../stores/session'
import { api, dateText, statusText } from '../api'
import { useCourseScope } from '../useCourseScope'
import Icon from '../components/Icon.vue'
import EmptyState from '../components/EmptyState.vue'
const scope=useCourseScope(), session=useSession(), rows=ref<any[]>([]), assignments=ref<any[]>([]), filter=ref('pending'), search=ref(''), loading=ref(true), selected=ref<any>(null), dialog=ref(false), busy=ref(false), scores=ref<number[]>([]), feedback=ref(''), errorType=ref('')
const visible=computed(()=>rows.value.filter(s=>(filter.value==='all'||filter.value==='pending'&&!s.grade?.reviewed&&!working(s)||filter.value==='reviewed'&&s.grade?.reviewed)&&(!search.value||s.student_name.includes(search.value)||s.assignment_title.includes(search.value))))
const pending=computed(()=>rows.value.filter(s=>!s.grade?.reviewed&&!working(s)).length)
const rubric=computed(()=>assignments.value.find(a=>a.id===selected.value?.assignment_id)?.rubric||[])
const working=(s:any)=>['pending','grading'].includes(s?.status)
async function refresh(){scope.stop();const [submissions,list]=await Promise.all([api.get(`/courses/${scope.courseId}/submissions`),api.get(`/courses/${scope.courseId}/assignments`)]);if(!scope.active())return;rows.value=submissions;assignments.value=list;if(submissions.some(working))scope.schedule(refresh)}
async function load(){loading.value=true;try{await refresh()}finally{if(scope.active())loading.value=false}}
onMounted(load)
function open(row:any){selected.value=row;scores.value=row.grade?.dimensions?.map((d:any)=>d.score??0)||assignments.value.find(a=>a.id===row.assignment_id)?.rubric.map(()=>0)||[];feedback.value=row.grade?.feedback||'';errorType.value=row.grade?.error_type||'';dialog.value=true}
async function save(){busy.value=true;try{await api.post(`/submissions/${selected.value.id}/review`,{scores:scores.value,feedback:feedback.value,error_type:errorType.value});dialog.value=false;await load();ElMessage.success('复核已保存')}finally{busy.value=false}}
</script>
<template>
  <div class="page-heading"><div><span class="eyebrow">HUMAN IN THE LOOP</span><h1>让每一份评价，都有教师把关</h1><p>核对建议评分，调整反馈内容，再把可靠的下一步交给学生。</p></div><span class="tag orange"><Icon name="review" :size="15" />{{ pending }} 份待复核</span></div>
  <button class="text-link task-refresh" @click="load"><Icon name="refresh" :size="14" />刷新提交状态</button><div class="review-note"><Icon name="shield" :size="23" /><div><b>AI 辅助，教师确认</b><p>历史规则反馈与模型输出属于辅助建议。复核后，评分、错题和学情统计会同步更新。</p></div></div><section class="panel"><div class="toolbar"><div class="tabs"><button v-for="f in [{id:'pending',name:'待复核'},{id:'reviewed',name:'已复核'},{id:'all',name:'全部提交'}]" :key="f.id" :class="{active:filter===f.id}" @click="filter=f.id">{{ f.name }}<span v-if="f.id==='pending'">{{ pending }}</span></button></div><div class="search-box"><Icon name="search" :size="17" /><input v-model="search" placeholder="搜索学生或作业" aria-label="搜索提交" /></div></div><div v-loading="loading" class="table-scroll"><table class="data-table"><thead><tr><th>学生 / 作业</th><th>提交时间</th><th>建议得分</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="s in visible" :key="s.id"><td><div class="file-cell"><span class="avatar avatar-sm">{{ s.student_name.slice(0,1) }}</span><div><b>{{ s.student_name }}<span v-if="s.is_seed" class="seed-inline">样例</span></b><small>{{ s.assignment_title }}</small></div></div></td><td class="muted small">{{ dateText(s.created_at,true) }}</td><td><b class="table-score">{{ s.grade?.score??'—' }}</b><small v-if="s.grade?.score!==null&&s.grade" class="muted"> 分</small></td><td><span :class="['tag',s.grade?.reviewed?'green':s.status==='failed'?'orange':'blue']">{{ s.grade?.reviewed?'教师已复核':statusText[s.status] }}</span></td><td><button class="text-link" data-testid="review-open" :disabled="working(s)" @click="open(s)">{{ s.grade?.reviewed?'查看并调整':'开始复核' }}<Icon name="chevron" :size="15" /></button></td></tr></tbody></table></div><EmptyState v-if="!loading&&!visible.length" title="当前没有匹配的提交" description="新提交会出现在待复核列表中。" /></section>
  <el-dialog v-model="dialog" title="作业评分复核" width="800px"><template v-if="selected"><div class="section-heading"><div><h3>{{ selected.student_name }} · {{ selected.assignment_title }}</h3><span class="small muted">{{ dateText(selected.created_at,true) }} 提交{{ selected.is_seed?' · 演示样例':'' }}</span></div><span class="tag blue">教师复核</span></div><pre class="detail-code">{{ selected.code }}</pre><div v-if="selected.error" class="error-box">{{ selected.error }}</div><form class="stack-form" @submit.prevent="save"><div class="review-scores"><label v-for="(r,i) in rubric" :key="r.name">{{ r.name }}<span><input v-model.number="scores[i]" type="number" min="0" :max="r.max_score" step="0.1" required /> / {{ r.max_score }}</span></label></div><div class="review-total">复核总分 <strong>{{ scores.reduce((a,b)=>a+Number(b||0),0).toFixed(1) }}</strong><span>分</span></div><label>反馈给学生<textarea v-model="feedback" required rows="4" maxlength="6000"></textarea></label><label>需要加入错题本的知识点<input v-model="errorType" maxlength="100" placeholder="没有需要复习的问题时可留空；满分时自动移除该错题" /></label><p class="small muted">保留历史复核版本。此处修改会同步更新对应错题；满分时移除该条错题记录。</p><div class="dialog-actions"><button class="btn btn-outline" type="button" @click="dialog=false">取消</button><button class="btn btn-primary" data-testid="review-save" :disabled="busy"><Icon name="check" :size="16" />{{ busy?'保存中…':'确认复核并保存' }}</button></div></form></template></el-dialog>
</template>
